package com.johnny.hotel.invoice;import com.johnny.hotel.exception.BusinessException;import com.johnny.hotel.pagination.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service @RequiredArgsConstructor @Transactional(readOnly=true) public class FinanceReadService{private final FinanceReadMapper mapper;private final InvoiceAccess access;private final PaginationSupport pages;public PageResult<FinanceOperationalRecord> read(String domain,Integer page,Integer size){access.financeRead(access.actor());var w=pages.window(page,size,true);List<FinanceOperationalRecord> rows;long total;switch(domain){case "bookings"->{rows=mapper.bookings(w.offset(),pages.limit(w));total=mapper.count("booking");}case "assignments"->{rows=mapper.assignments(w.offset(),pages.limit(w));total=mapper.count("stay_room_assignment");}case "rooms"->{rows=mapper.rooms(w.offset(),pages.limit(w));total=mapper.count("room");}case "stays"->{rows=mapper.stays(w.offset(),pages.limit(w));total=mapper.count("stay");}case "guests"->{rows=mapper.guests(w.offset(),pages.limit(w));total=mapper.count("guest_profile");}case "cleaning"->{rows=mapper.cleaning(w.offset(),pages.limit(w));total=mapper.count("cleaning_record");}case "inspections"->{rows=mapper.inspections(w.offset(),pages.limit(w));total=mapper.count("housekeeping_inspection");}case "work-orders"->{rows=mapper.workOrders(w.offset(),pages.limit(w));total=mapper.count("room_work_order");}case "turnovers"->{rows=mapper.turnovers(w.offset(),pages.limit(w));total=mapper.count("room_turnover_task");}default->throw new BusinessException(404,"Finance record domain not found");}return pages.result(w,rows,total);}}
